const sourceItem = $input.first();
const binary = sourceItem.binary || {};
const binaryKeys = Object.keys(binary);

if (!binaryKeys.length) {
  throw new Error('No uploaded file was found. Upload the CSV in the multipart form-data field named "file".');
}

const binaryPropertyName = binaryKeys.includes('file') ? 'file' : binaryKeys[0];
const fileMeta = binary[binaryPropertyName] || {};
const fileName = fileMeta.fileName || 'statement.csv';
const mimeType = fileMeta.mimeType || 'text/csv';
const fileBuffer = await this.helpers.getBinaryDataBuffer(0, binaryPropertyName);
const fileContent = fileBuffer.toString('utf8').replace(/^\uFEFF/, '');

const body = sourceItem.json?.body || {};
const json = sourceItem.json || {};
const bank = body.bank || json.bank || '';
const currency = body.currency || json.currency || 'USD';
const erpnextBankAccount = body.erpnextBankAccount || json.erpnextBankAccount || '';
const company = body.company || json.company || '';

return [{
  json: {
    bank,
    currency,
    erpnextBankAccount,
    company,
    fileName,
    mimeType,
    binaryPropertyName,
    fileContent,
  }
}];

function parseCsvLine(line, delimiter = ',') {
  const out = [];
  let cur = '';
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    const next = line[i + 1];

    if (ch === '"') {
      if (inQuotes && next === '"') {
        cur += '"';
        i++;
      } else {
        inQuotes = !inQuotes;
      }
    } else if (ch === delimiter && !inQuotes) {
      out.push(cur);
      cur = '';
    } else {
      cur += ch;
    }
  }

  out.push(cur);
  return out;
}

function detectDelimiter(text) {
  const firstLines = text.split(/\r?\n/).slice(0, 10).join('\n');
  const commaCount = (firstLines.match(/,/g) || []).length;
  const tabCount = (firstLines.match(/\t/g) || []).length;
  const semicolonCount = (firstLines.match(/;/g) || []).length;

  if (tabCount > commaCount && tabCount > semicolonCount) return '\t';
  if (semicolonCount > commaCount) return ';';
  return ',';
}

function normalizeHeader(h) {
  return String(h || '')
    .trim()
    .toLowerCase()
    .replace(/^\uFEFF/, '')
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');
}

function cleanValue(v) {
  if (v === undefined || v === null) return '';
  return String(v).trim();
}

function normalizeForKey(v) {
  return cleanValue(v)
    .toUpperCase()
    .replace(/\s+/g, ' ')
    .trim();
}

function parseAmount(v) {
  const s = cleanValue(v)
    .replace(/[$,]/g, '')
    .replace(/\((.*?)\)/, '-$1');

  if (!s) return 0;
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

function parseDate(v) {
  const s = cleanValue(v);
  if (!s) return '';

  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;

  const m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (m) {
    const mm = m[1].padStart(2, '0');
    const dd = m[2].padStart(2, '0');
    const yyyy = m[3];
    return `${yyyy}-${mm}-${dd}`;
  }

  const d = new Date(s);
  if (!isNaN(d.getTime())) {
    return d.toISOString().slice(0, 10);
  }

  return s;
}

function firstPresent(obj, keys) {
  for (const k of keys) {
    if (obj[k] !== undefined && obj[k] !== null && String(obj[k]).trim() !== '') {
      return obj[k];
    }
  }
  return '';
}

function cyrb53(str, seed = 0) {
  let h1 = 0xdeadbeef ^ seed;
  let h2 = 0x41c6ce57 ^ seed;
  for (let i = 0, ch; i < str.length; i++) {
    ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return 4294967296 * (2097151 & h2) + (h1 >>> 0);
}

function makeSyntheticId(parts, prefix = 'TXN') {
  const canonical = parts.map(normalizeForKey).join('|');
  const hash = cyrb53(canonical).toString(16).toUpperCase();
  return `${prefix}-${hash}`;
}

const input = items[0].json;
const rawText = input.fileContent || '';

if (!rawText || !String(rawText).trim()) {
  throw new Error('No file content was provided to the normalization step.');
}

const text = String(rawText).replace(/\r\n/g, '\n').replace(/\r/g, '\n');
const delimiter = detectDelimiter(text);
const lines = text.split('\n').filter(line => line.trim() !== '');

if (!lines.length) {
  throw new Error('Uploaded file appears to be empty.');
}

let headerIndex = -1;
let headers = [];

for (let i = 0; i < Math.min(lines.length, 20); i++) {
  const cols = parseCsvLine(lines[i], delimiter).map(normalizeHeader);
  const hasDate =
    cols.includes('processed_date') ||
    cols.includes('posting_date') ||
    cols.includes('effective_date') ||
    cols.includes('date');

  const hasDesc =
    cols.includes('description') ||
    cols.includes('memo') ||
    cols.includes('extended_description');

  const hasAmount =
    cols.includes('amount') ||
    cols.includes('debit') ||
    cols.includes('credit');

  if (hasDate && hasDesc && hasAmount) {
    headerIndex = i;
    headers = cols;
    break;
  }
}

if (headerIndex === -1) {
  throw new Error(
    'Could not find a usable header row. First lines were: ' +
      lines.slice(0, 5).join(' | ')
  );
}

const currency = cleanValue(input.currency || 'USD');
const bankName = cleanValue(input.bank || '');
const erpnextBankAccount = cleanValue(input.erpnextBankAccount || '');
const company = cleanValue(input.company || '');
const output = [];

for (let i = headerIndex + 1; i < lines.length; i++) {
  const rawCols = parseCsvLine(lines[i], delimiter);
  if (!rawCols.some(v => cleanValue(v) !== '')) continue;

  const row = {};
  for (let c = 0; c < headers.length; c++) {
    row[headers[c]] = cleanValue(rawCols[c] || '');
  }

  const dateRaw = firstPresent(row, ['processed_date', 'posting_date', 'effective_date', 'date']);
  const descriptionRaw = firstPresent(row, ['description', 'memo', 'extended_description']);
  const checkNumber = firstPresent(row, ['check_number']);
  const bankTransactionId = firstPresent(row, ['transaction_id']);
  const referenceNumber = firstPresent(row, ['reference_number']);
  const transactionType = firstPresent(row, ['transaction_type', 'type', 'credit_or_debit']);
  let debit = 0;
  let credit = 0;

  if (row.amount && row.credit_or_debit) {
    const amt = Math.abs(parseAmount(row.amount));
    const direction = cleanValue(row.credit_or_debit).toLowerCase();

    if (direction.includes('debit')) {
      debit = amt;
    } else if (direction.includes('credit')) {
      credit = amt;
    }
  } else if (row.debit || row.credit) {
    debit = Math.abs(parseAmount(row.debit));
    credit = Math.abs(parseAmount(row.credit));
  } else if (row.amount) {
    const amt = parseAmount(row.amount);
    if (amt < 0) {
      debit = Math.abs(amt);
    } else if (amt > 0) {
      credit = amt;
    }
  }

  const parsedDate = parseDate(dateRaw);
  const description = descriptionRaw || referenceNumber || bankTransactionId || checkNumber || '';

  if (!parsedDate || !description || (!debit && !credit)) {
    continue;
  }

  const directionLabel = debit ? 'Debit' : 'Credit';
  const amountForKey = debit ? debit.toFixed(2) : credit.toFixed(2);
  const syntheticPrefix = bankName && bankName.toLowerCase().includes('high plains') ? 'HPB' : 'TXN';
  const syntheticId = makeSyntheticId([
    erpnextBankAccount || bankName,
    parsedDate,
    directionLabel,
    amountForKey,
    description,
    checkNumber,
  ], syntheticPrefix);

  const finalTransactionId = bankTransactionId || referenceNumber || syntheticId;
  const finalReferenceNumber = referenceNumber || bankTransactionId || syntheticId;

  output.push({
    json: {
      bank: bankName,
      sourceFile: input.fileName || 'statement.csv',
      date: parsedDate,
      bank_account: erpnextBankAccount,
      company,
      deposit: credit || 0,
      withdrawal: debit || 0,
      currency,
      description,
      reference_number: finalReferenceNumber,
      transaction_id: finalTransactionId,
      transaction_type: transactionType || directionLabel,
    }
  });
}

if (!output.length) {
  throw new Error(
    `No usable transaction rows were found. Header row detected at line ${headerIndex + 1} using delimiter "${delimiter}". Parsed headers: ${headers.join(', ')}`
  );
}

return output;

let created = 0;
let duplicates = 0;
let errors = 0;
const lines = [];

function extractTxIdFromText(text) {
  if (!text) return "";
  const patterns = [
    /Duplicate entry '([^']+)' for key 'transaction_id'/i,
    /transaction_id['"]?\s*[:=]\s*['"]([^'"]+)['"]/i,
    /"transaction_id":"([^"]+)"/i,
  ];

  for (const re of patterns) {
    const m = text.match(re);
    if (m) return m[1];
  }
  return "";
}

for (const item of items) {
  const j = item.json || {};
  const createdDoc = j.data || null;
  const errorObj = j.error || null;

  const errorText = [
    errorObj?.message,
    errorObj?.description,
    j.message,
    j.errorMessage,
    JSON.stringify(errorObj || {}),
  ]
    .filter(Boolean)
    .join(" | ");

  const lowerError = errorText.toLowerCase();

  const date =
    createdDoc?.date ||
    j.source_date ||
    j.date ||
    j["Date"] ||
    "(unknown)";

  const txId =
    createdDoc?.transaction_id ||
    j.source_transaction_id ||
    j.transaction_id ||
    j["Transaction ID"] ||
    extractTxIdFromText(errorText) ||
    "(unknown)";

  if (createdDoc && createdDoc.name) {
    created++;
    lines.push(`• CREATED - ${date} - ${txId} - ${createdDoc.name}`);
  } else if (
    lowerError.includes("duplicate entry") ||
    lowerError.includes("transaction id must be unique") ||
    lowerError.includes("uniquevalidationerror")
  ) {
    duplicates++;
    lines.push(`• DUPLICATE - ${date} - ${txId}`);
  } else {
    errors++;
    lines.push(`• ERROR - ${date} - ${txId} - ${errorText || JSON.stringify(j)}`);
  }
}

return [
  {
    json: {
      created,
      duplicates,
      errors,
      total: items.length,
      preview: lines.slice(0, 20),
    },
  },
];
